import { NotFoundError } from "../domain/domain-errors";
import { OrderRepository } from "../domain/order-repository";
import { StockReservationService } from "../domain/stock-reservation-service";
import { OrderDto, toOrderDto } from "./dtos";

export class CancelOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly reservations: StockReservationService,
  ) {}

  async execute(orderId: string): Promise<OrderDto> {
    const order = await this.orders.findById(orderId);
    if (!order) throw new NotFoundError(`Order ${orderId} not found`);
    order.cancel();
    await this.reservations.release(order.lines);
    await this.orders.save(order);
    return toOrderDto(order);
  }
}

=====SOURCE-END=====

